 /** Split a template into text and tag tokens. See README.md. */
 export function tokenize(template: string): Token[] {
-  throw new Error("not implemented");
+  const tokens: Token[] = [];
+  let pos = 0;
+
+  const pushText = (text: string) => {
+    if (text === "") return;
+    const last = tokens[tokens.length - 1];
+    if (last?.kind === "text") last.text += text;
+    else tokens.push({ kind: "text", text });
+  };
+
+  while (pos < template.length) {
+    const open = template.indexOf("{{", pos);
+    if (open === -1) {
+      pushText(template.slice(pos));
+      break;
+    }
+    pushText(template.slice(pos, open));
+
+    const raw = template.startsWith("{{{", open);
+    const close = raw ? "}}}" : "}}";
+    const start = open + (raw ? 3 : 2);
+    const end = template.indexOf(close, start);
+    if (end === -1) throw new Error("unterminated tag");
+
+    const body = template.slice(start, end).trim();
+    pos = end + close.length;
+
+    if (raw) {
+      tokens.push({ kind: "value", expr: body, raw: true });
+      continue;
+    }
+    const ifMatch = /^#if\s+([\s\S]*)$/.exec(body);
+    if (ifMatch) {
+      tokens.push({ kind: "if", path: ifMatch[1].trim() });
+    } else if (body === "else") {
+      tokens.push({ kind: "else" });
+    } else if (body === "/if") {
+      tokens.push({ kind: "end" });
+    } else {
+      tokens.push({ kind: "value", expr: body, raw: false });
+    }
+  }
+  return
